public sealed class OutboxInterceptor(TimeProvider clock) : SaveChangesInterceptor
{
    public override ValueTask<InterceptionResult<int>> SavingChangesAsync(
        DbContextEventData e, InterceptionResult<int> r, CancellationToken ct = default)
    {
        var db = e.Context!;
        var events = db.ChangeTracker.Entries<IHasDomainEvents>()
            .SelectMany(x => x.Entity.PullDomainEvents()).ToList();
        db.Set<OutboxMessage>().AddRange(events.Select(ev => OutboxMessage.From(ev, clock.GetUtcNow())));
        return base.SavingChangesAsync(e, r, ct);
    }
}

